lessons.solution:
def shipping_cost(weight_kg, express=False):
    if weight_kg <= 0:
        return 0
    if weight_kg <= 1:
        cost = 5
    elif weight_kg <= 5:
        cost = 9
    else:
        cost = 15
    return cost * 2 if express else cost


def is_leap(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0

