lessons.solution:
def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps


def first_negative_index(numbers):
    for i, number in enumerate(numbers):
        if number < 0:
            return i
    return -1

