lessons.solution:
def parse_age(text):
    age = int(text)
    if not 0 <= age <= 150:
        raise ValueError(f"age out of range: {age}")
    return age


def safe_ratio(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

